MultiLanguageSpellData['ru'][90415] = {name = "[q0]Крылатый шлем Молота Глубин", additional_info = "Применение: 2 сек 5\n[q]Судя по размерам шлема, у тана Молота Глубин из клана Черного Железа была удивительно большая голова... или удивительно толстые щеки.\n[q0]Крылатый шлем Молота Глубин\nСтановится персональным при получении"}
