MultiLanguageSpellData['ru'][90831] = {name = "[q0]Демонический бич", additional_info = "Применение: 2 сек 5\n[q]С приходом Гул'дана к власти чернокнижники приобрели авторитет среди орков. Этот бич суккуба сплетен из плоти нескольких существ, некоторые из них явно были гуманоидами.\n[q0]Демонический бич\nСтановится персональным при получении"}
MultiLanguageSpellData['ru'][90832] = {name = "[q0]Глазурованная глиняная плитка", additional_info = "Применение: 2 сек 5\n[q]Несомненно, эта плитка некогда украшала собой стены или пол дренорской крепости или парадной залы. На плитке изображены стада животных, пасущихся на желтых и зеленых полях – именно так сегодня выглядит Награнд. Рисунок окантован орнаментом из черных и коричневых квадратов.\n[q0]Глазурованная глиняная плитка\nСтановится персональным при получении"}
