MultiLanguageSpellData['ru'][93433] = {name = "Атака из-под земли", additional_info = "10 ед. концентрации + 5/сек.\n{Направляемое (Применение:} 8 сек) {Восстановление: 14 сек}\n[q]Червь зарывается в землю, вызывая над собой землетрясение, наносящее [(([12.1% of Attack Power]) + ((Сила атаки дальнего боя * 0.60) * 0.096)) * 8 * (1 + Универсальность) * 1 ] ед. урона от сил природы в течение 8 сек."}
MultiLanguageSpellData['ru'][93440] = {name = "[q0]Дворфийские детские носочки", additional_info = "Применение: 2 сек 5\n[q]Сначала вам показалось, что носочки окаменели. Но анализ показал, что это все-таки грязь.\n[q0]Дворфийские детские носочки\nСтановится персональным при получении"}
MultiLanguageSpellData['ru'][93441] = {name = "[q0]Ожерелье с подвеской Элуны", additional_info = "Применение: 2 сек 5\n[q]Элуна – главная богиня ночных эльфов. Ее символом считается большая из двух лун, Белая Дама. Элуна – богиня мира, но ее образ жизни далек от мирного. Одно из ее воплощений – Ночная Воительница, она собирает души павших в бою доблестных воинов и отправляет их в вечное путешествие по небосклону в облике звезд.\n[q0]Ожерелье с подвеской Элуны\nСтановится персональным при получении"}
MultiLanguageSpellData['ru'][93442] = {name = "[q0]Осколок окаменевшего дерева", additional_info = "Применение: 2 сек 5\n[q]Тканей для изучения практически не осталось, но структура волокон превосходно сохранилась. Скорее всего, это растение принадлежало к семейству пальмовых или цикадовых.\n[q0]Осколок окаменевшего дерева\nСтановится персональным при получении"}
MultiLanguageSpellData['ru'][93443] = {name = "[q0]Странный бархатистый червь", additional_info = "Применение: 2 сек 5\n[q]Это, по-видимому, своеобразное переходное звено между червями и членистоногими. На вытянутом, покрытом бархатистой шерстью теле существа легко различимы жесткие, похожие на щетинки ножки, похожие на конечности насекомых или ракообразных.\n[q0]Странный бархатистый червь\nСтановится персональным при получении"}
MultiLanguageSpellData['ru'][93444] = {name = "[q0]Изысканный обеденный прибор Кровавого Скальпа", additional_info = "Применение: 2 сек 5\n[q]По правде говоря, это просто здоровенный нож, но в племени Кровавого Скальпа использование любого столового прибора считается признаком изысканных манер.\n[q0]Изысканный обеденный прибор Кровавого Скальпа\nСтановится персональным при получении"}
