MultiLanguageSpellData['ru'][114011] = {name = "Удар наотмашь", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Удар сплеча наносит 150% урона от оружия и увеличивает наносимый цели физический урон на 20% в течение 10 сек. Эффект суммируется."}
