MultiLanguageSpellData['ru'][121836] = {name = "Сапфировая пантера", additional_info = "Применение: 1.5 сек\n[q]Позволяет призывать и отпускать ездовую сапфировую пантеру.\n[q]\"Согласно легенде, древний император Пандарии впервые смастерил пантеру из драгоценного камня для своего сына, когда его брат-близнец скончался от болезни.\"\nПрофессия:\nювелирное дело"}
MultiLanguageSpellData['ru'][121837] = {name = "Нефритовая пантера", additional_info = "Применение: 1.5 сек\n[q]Позволяет призывать и отпускать верховую нефритовую пантеру.\n[q]\"Согласно легенде, древний император Пандарии впервые смастерил пантеру из драгоценного камня для своего сына, когда его брат-близнец скончался от болезни.\"\nПрофессия:\nювелирное дело"}
