MultiLanguageSpellData['ru'][132466] = {name = "Волна ци", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Волна энергии ци накрывает союзников и противников, нанося ([20% of Attack Power]) ед. урона от сил природы или восполняя ([60% of Attack Power]) ед. здоровья. Переходит до 7 раза на цели в радиусе 25 м."}
