MultiLanguageSpellData['ru'][132469] = {name = "Тайфун", additional_info = "Радиус действия: 15 м\n{Мгновенное действие} {Восстановление: 30 сек}\n[q]Вызывает тайфун, который отбрасывает противников в радиусе 15 м перед вами и снижает их скорость передвижения на 50% на 6 сек. Можно применять в любом облике."}
