MultiLanguageSpellData['ru'][139779] = {name = "Древний сборник сока", additional_info = "Применение: 2 сек\n[q]Перед употреблением сока кипари богомолы любят дать ему вызреть. Для этого используют сборники сока. Присмотревшись к этому древнему сборнику сока, вы поймете, что с течением времени внешний вид этой утвари мало изменился."}
MultiLanguageSpellData['ru'][139780] = {name = "Молящийся богомол", additional_info = "Применение: 2 сек\n[q]Эта статуя Клакси'ва датируется эпохой появления титанов. На постаменте выгравирована молитва \"к тому, что имеет семь голов\". В древнем языке слово \"клакси\" значило \"жрец\"."}
MultiLanguageSpellData['ru'][139781] = {name = "Бездействующий звуковой маяк", additional_info = "Применение: 2 сек\n[q]Никто, кроме самих богомолов, не может постичь технологию создания их звуковых маяков. Полагают, что во многом устройство маяков опирается на физиологию богомолов. Этот древний маяк полностью сохранен, но совершенно бесполезен без богомола, который мог бы им оперировать."}
MultiLanguageSpellData['ru'][139782] = {name = "Останки Идеала", additional_info = "Применение: 2 сек\n[q]Как показывает эта находка, сохранение в янтаре довольно рисковано. От этого Идеала осталась одна голова. Предположительно артефакт относится к эпохе до пандаренской революции, хотя точное датирование представляется невозможным."}
MultiLanguageSpellData['ru'][139783] = {name = "Лампа богомолов", additional_info = "Применение: 2 сек\n[q]Эта лампа светится, но не огнем и не магией. Если заглянуть внутрь, можно увидеть множество светящихся насекомых, застывших в янтаре."}
MultiLanguageSpellData['ru'][139784] = {name = "Сборник пыльцы", additional_info = "Применение: 2 сек\n[q]Трудно утверждать наверняка, но больше всего это похоже на некий сборник пыльцы."}
MultiLanguageSpellData['ru'][139785] = {name = "Резервуар для сока кипари", additional_info = "Применение: 2 сек\n[q]Этот резервуар выглядит, как янтарный, но на самом деле он изготовлен из выделений куньчунов, как и большая часть домашней утвари богомолов."}
MultiLanguageSpellData['ru'][139786] = {name = "[q3]Небесный клинок богомолов", additional_info = "Применение: 2 сек\n[q]Этот старинный \"Небесный клинок\" создавался для вооружения летучих богомолов. Он необычайно легок, хорошо сбалансирован и подходит для широких взмахов над головой в полете. Большинство богомолов сбрасывает крылья во время обряда инициации, после чего начинает носить тяжелые доспехи и оружие, так что подобный клинок – редчайшая находка. Вполне возможно, что некогда им сражался Идеал.\n[q3]Небесный клинок богомолов\n[q7]Привязывается к отряду\nОдноручное Меч\nУрон: 4 - 8 Скорость 2.60\n(2.3 ед. урона в секунду)\n+2 к силе\n+3 к выносливости\n[q2]+ 2 к скорости\n[q2]+ 2 к искусности\nПрочность: 90 / 90\nТребуется\n[q]\"Этот артефакт уже записан в ваш журнал археологических находок. На вкладке \"Собранные артефакты\" вы можете найти его описание.\""}
MultiLanguageSpellData['ru'][139787] = {name = "[q3]Генератор звуковых импульсов", additional_info = "Применение: 2 сек\n[q]Богомолы способны издавать и воспринимать звуки в более широком звуковом диапазоне, чем другие расы смертных. Это врожденное свойство позволяет им создавать подобное оружие. Звуковые волны, издаваемые этим инструментом, вызывают разрывы мышц и органов на клеточном уровне. При прямом воздействии на цель происходит полное расщепление.\n[q3]Генератор звуковых импульсов\n[q7]Привязывается к отряду\nДальний бой Огнестрельное\nУрон: 6 - 12 Скорость 3.00\n(3.0 ед. урона в секунду)\n+4 к ловкости\n+6 к выносливости\n[q2]+ 4 к скорости\n[q2]+ 4 к искусности\nПрочность: 100 / 100\nТребуется\n[q]\"Этот артефакт уже записан в ваш журнал археологических находок. На вкладке \"Собранные артефакты\" вы можете найти его описание.\""}
