MultiLanguageSpellData['ru'][156150] = {name = "Течение мыслей", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]За счет притока магической энергии наносимый вами урон увеличивается. Величина дополнительного урона изменяется во время боя, постепенно увеличиваясь до 10%, а затем уменьшаясь до 2%. Этот цикл длится 10 сек."}
MultiLanguageSpellData['ru'][156151] = {name = "Молоток для мяса", additional_info = "Дистанция ближнего боя\nСледующая атака\n[q]Молоток Мясника бьет по цели, нанося большой физический урон, и увеличивает урон, получаемый от дальнейших таких атак, на 50%\n\n Эта атака всегда попадает по цели."}
