MultiLanguageSpellData['ru'][162518] = {name = "Земляной столп", additional_info = "Мгновенное действие\n[q]Тектоник вызывает земляной столп. В выбранном месте земля некоторое время трясется, после чего из-под земли стремительно вырастает столп, убивающий всех, кто стоял на этом месте.\n\n Тектоник использует эту способность, когда запас его энергии достигает 25 ед."}
